import { type Edge, edges } from './explore.ts'
import { OUTCOMES, WAITS, WAIT_REASONS } from './issue.ts'

export const DIAGRAM_START =
  '<!-- issue-machine:start (generated by apps/server/scripts/issue-diagram.ts from TABLE) -->'
export const DIAGRAM_END = '<!-- issue-machine:end -->'

/** `woken (timer, wall)`: an event with the waits it enters or leaves; none named when it takes every wait. */
function labels(group: readonly Edge[]): string {
  const byKind = new Map<string, string[]>()
  for (const edge of group) {
    const reasons = byKind.get(edge.kind) ?? []
    if (edge.reason) reasons.push(edge.reason)
    byKind.set(edge.kind, reasons)
  }
  return [...byKind]
    .map(([kind, reasons]) =>
      reasons.length === 0 || reasons.length === WAIT_REASONS.length ? kind : `${kind} (${reasons.join(', ')})`,
    )
    .join(', ')
}

/** The block between the markers in `docs/language.md`: the states and events as `TABLE` has them, and the waits. */
export function issueDiagram(): string {
  const byPair = new Map<string, Edge[]>()
  for (const edge of edges()) {
    const pair = `${edge.from} --> ${edge.to}`
    byPair.set(pair, [...(byPair.get(pair) ?? []), edge])
  }
  const lines = [
    '```mermaid',
    'stateDiagram-v2',
    '  [*] --> settling: filed',
    ...[...byPair].map(([pair, group]) => `  ${pair}: ${labels(group)}`),
    '  closed --> [*]',
    '```',
    '',
    '| Wait | Exit | Stall | Ends |',
    '|-|-|-|-|',
    ...WAIT_REASONS.map((reason) => {
      const wait = WAITS[reason]
      return `| \`${reason}\` | ${wait.exit === 'person' ? 'a person' : 'no person'} | ${wait.stall ? 'yes' : 'no'} | ${wait.ends} |`
    }),
    '',
    `Outcomes of \`closed\`: ${OUTCOMES.map((o) => `\`${o}\``).join(', ')}.`,
  ]
  return `${DIAGRAM_START}\n\n${lines.join('\n')}\n\n${DIAGRAM_END}`
}

/** The document with its block replaced; null when the markers are missing. */
export function withDiagram(document: string): string | null {
  const start = document.indexOf(DIAGRAM_START)
  const end = document.indexOf(DIAGRAM_END)
  if (start < 0 || end < start) return null
  return document.slice(0, start) + issueDiagram() + document.slice(end + DIAGRAM_END.length)
}
